begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values
('a6000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','catalog-admin@test.local','x',now(),now(),now()),
('a6000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','catalog-office@test.local','x',now(),now(),now()),
('a6000000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','catalog-tech@test.local','x',now(),now(),now()),
('a6000000-0000-4000-8000-000000000004','00000000-0000-0000-0000-000000000000','authenticated','authenticated','catalog-client@test.local','x',now(),now(),now());
insert into public.staff_users(user_id,role) values('a6000000-0000-4000-8000-000000000001','admin'),('a6000000-0000-4000-8000-000000000002','office'),('a6000000-0000-4000-8000-000000000003','technician');
create function pg_temp.item(p_code text default 'TEST-CATALOG-001') returns jsonb language sql as $$select jsonb_build_object('code',p_code,'name','Montaż katalog test','category','service','unit','hour','costCents',3800,'saleCents',6500,'vatBasisPoints',2300,'manufacturer','','model','','supplier','Dostawca testowy','description','Zakres testowy','archived',false)$$;
set local role anon;
select throws_ok($$select public.list_catalog_items()$$,'42501',null,'Anonymous cannot read catalog RPC');
select throws_ok($$select * from public.catalog_items$$,'42501',null,'Anonymous has no raw price access');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000001','{}')$$,'42501',null,'Anonymous cannot save');
set local role authenticated;
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000001',true);
select is(public.save_catalog_item('c6000000-0000-4000-8000-000000000001',pg_temp.item()),'c6000000-0000-4000-8000-000000000001'::uuid,'Admin can create item');
select is(public.save_catalog_item('c6000000-0000-4000-8000-000000000001',pg_temp.item()),'c6000000-0000-4000-8000-000000000001'::uuid,'Exact create retry is idempotent');
select is((select count(*)::int from public.catalog_items where code='TEST-CATALOG-001'),1,'Retry did not duplicate item');
select is((select version from public.catalog_items where code='TEST-CATALOG-001'),0,'Retry did not increment version');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000001',pg_temp.item()||'{"saleCents":7000}')$$,'40001',null,'Same create ID cannot change payload');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000002',pg_temp.item('test-catalog-001'))$$,'23505',null,'Codes unique regardless of case');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000002',pg_temp.item()||'{"costCents":-1}')$$,'22023',null,'Negative money rejected');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000002',pg_temp.item()||'{"saleCents":1.25}')$$,'22023',null,'Fractional grosze rejected');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000002',pg_temp.item()||'{"vatBasisPoints":10001}')$$,'22023',null,'VAT bounded');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000002',pg_temp.item()||'{"created_by":"a6000000-0000-4000-8000-000000000002"}')$$,'22023',null,'Cannot forge ownership');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000002',pg_temp.item()||'{"category":null}')$$,'22023',null,'Null mandatory fields rejected');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000002',pg_temp.item()||'{"unit":"anything"}')$$,'22023',null,'Unknown unit rejected');
select throws_ok($$update public.catalog_items set sale_cents=0$$,'42501',null,'Raw updates forbidden even for manager');
select throws_ok($$delete from public.catalog_items$$,'42501',null,'Hard deletion forbidden');
select is((public.list_catalog_items('dostawca testowy','service','active')->>'total')::int,1,'Search includes supplier and category');
select is((public.list_catalog_items('%','all','all')->>'total')::int,0,'Search wildcards are literal');
select is((public.list_catalog_items('katalog test','device','all')->>'total')::int,0,'Category filter applies');
select is((public.list_catalog_items('katalog test','all','all',2)->'items'), '[]'::jsonb,'Pagination does not repeat first page');
select throws_ok($$select public.list_catalog_items('', 'all','active',0)$$,'22023',null,'Invalid page rejected');
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000002',true);
select is(public.save_catalog_item('c6000000-0000-4000-8000-000000000001',pg_temp.item()||'{"saleCents":7000}',0),'c6000000-0000-4000-8000-000000000001'::uuid,'Office may update with current version');
select is((select version from public.catalog_items where code='TEST-CATALOG-001'),1,'Update advances version');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000001',pg_temp.item(),0)$$,'40001',null,'Stale editor cannot overwrite newer prices');
select is(public.save_catalog_item('c6000000-0000-4000-8000-000000000001',pg_temp.item()||'{"saleCents":7000,"archived":true}',1),'c6000000-0000-4000-8000-000000000001'::uuid,'Archive preserves record');
select is((public.list_catalog_items('TEST-CATALOG-001','all','active')->>'total')::int,0,'Archived hidden in active view');
select is((public.list_catalog_items('TEST-CATALOG-001','all','archived')->>'total')::int,1,'Archived visible in archive');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000002',pg_temp.item())$$,'23505',null,'Archived code remains reserved');
select is(public.save_catalog_item('c6000000-0000-4000-8000-000000000001',pg_temp.item(),2),'c6000000-0000-4000-8000-000000000001'::uuid,'Restore returns item to active view');
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000003',true);
select is((select count(*)::int from public.catalog_items),0,'Technician RLS hides raw prices');
select throws_ok($$select public.list_catalog_items()$$,'42501',null,'Technician cannot read price RPC');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000003',pg_temp.item('TEST-TECH'))$$,'42501',null,'Technician cannot write');
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000004',true);
select is((select count(*)::int from public.catalog_items),0,'Client RLS hides raw prices');
select throws_ok($$select public.list_catalog_items()$$,'42501',null,'Client cannot read price RPC');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000003',pg_temp.item('TEST-CLIENT'))$$,'42501',null,'Client cannot write');
reset role;
insert into public.account_access(user_id,blocked) values('a6000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.audit_logs where table_name='catalog_items' and row_id='c6000000-0000-4000-8000-000000000001'),4,'Audit records create, update, archive and restore once');
set local role authenticated;
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.catalog_items),0,'Blocked office immediately loses raw access');
select throws_ok($$select public.list_catalog_items()$$,'42501',null,'Blocked office cannot read RPC with existing session');
select throws_ok($$select public.save_catalog_item('c6000000-0000-4000-8000-000000000003',pg_temp.item('TEST-BLOCKED'))$$,'42501',null,'Blocked office cannot save');
select * from finish();
rollback;
